// Extrai nome do anúncio (coluna B) + link do arquivo (K = feed, L = story).
//
// Por que não dá para usar o node "Google Sheets": ele devolve só o VALOR da
// célula. Nas colunas K e L o valor é o nome do arquivo e o endereço fica no
// hyperlink — que só aparece pedindo os campos de formatação da API.
//
// A API guarda o link em três lugares diferentes conforme como ele foi criado:
//   hyperlink                          -> fórmula =HYPERLINK()
//   userEnteredFormat.textFormat.link  -> link aplicado à célula inteira
//   textFormatRuns[].format.link       -> link inserido pelo menu (o caso daqui)
// Por isso testamos os três, nessa ordem.

const COL = { nome: 1, feed: 10, story: 11 }; // B, K, L (base 0)

const linkDe = (v) =>
  v?.hyperlink ||
  v?.userEnteredFormat?.textFormat?.link?.uri ||
  (v?.textFormatRuns || []).map((r) => r?.format?.link?.uri).find(Boolean) ||
  '';

const fileId = (u) =>
  (u.match(/\/file\/d\/([^/]+)/) || [])[1] ||
  (u.match(/[?&]id=([^&]+)/) || [])[1] ||
  '';

const tipoDe = (nome) =>
  /_vid_/i.test(nome) ? 'video' : (/_car_/i.test(nome) ? 'carrossel' : 'imagem');

const resp = $input.first().json;
const rowData = resp?.sheets?.[0]?.data?.[0]?.rowData || [];
if (rowData.length === 0) {
  throw new Error('A API não devolveu rowData — confira o nome da aba em "ranges" e se a credencial tem escopo de Sheets.');
}

const linhas = [];
for (let i = 1; i < rowData.length; i++) { // pula o cabeçalho
  const v = rowData[i]?.values || [];
  const nome = (v[COL.nome]?.formattedValue || '').trim();
  if (!/^seal_ad/i.test(nome)) continue; // ignora legendas e linhas em branco

  const feed = fileId(linkDe(v[COL.feed]));
  const story = fileId(linkDe(v[COL.story]));
  if (!feed && !story) continue; // sem arquivo, não entra na fila

  linhas.push({
    ad_name: nome,
    tipo: tipoDe(nome),
    drive_feed_id: feed || null,
    drive_story_id: story || null,
  });
}

// dedup por nome (a planilha repete o mesmo criativo em linhas diferentes)
const unicos = [...new Map(linhas.map((l) => [l.ad_name.toLowerCase(), l])).values()];
if (unicos.length === 0) {
  throw new Error('Nenhum criativo com link encontrado — os hyperlinks podem ter se perdido na conversão para Sheets.');
}

return [{ json: { total: unicos.length, rows: unicos } }];
